import java.util.concurrent.atomic.AtomicLong;

/**
 * 雪花算法完整实现（含时钟回拨处理）
 * 位结构: 1(符号) + 41(时间戳) + 10(机器ID) + 12(序列号)
 */
public class SnowflakeIdGenerator {
    // 起始时间戳: 2024-01-01 00:00:00 UTC (定制, 减少时间戳位数消耗)
    private static final long EPOCH = 1704067200000L;
    private static final long WORKER_ID_BITS = 5L;
    private static final long DATACENTER_ID_BITS = 5L;
    private static final long SEQUENCE_BITS = 12L;

    private static final long MAX_WORKER_ID = ~(-1L << WORKER_ID_BITS);       // 31
    private static final long MAX_DATACENTER_ID = ~(-1L << DATACENTER_ID_BITS); // 31
    private static final long SEQUENCE_MASK = ~(-1L << SEQUENCE_BITS);          // 4095

    private static final long WORKER_ID_SHIFT = SEQUENCE_BITS;                  // 12
    private static final long DATACENTER_ID_SHIFT = SEQUENCE_BITS + WORKER_ID_BITS; // 17
    private static final long TIMESTAMP_SHIFT = SEQUENCE_BITS + WORKER_ID_BITS + DATACENTER_ID_BITS; // 22

    // 允许的最大回拨毫秒数, 超过则拒绝发号
    private static final long MAX_BACKWARD_MS = 5L;

    private final long workerId;
    private final long datacenterId;
    private long sequence = 0L;
    private long lastTimestamp = -1L;

    public SnowflakeIdGenerator(long workerId, long datacenterId) {
        if (workerId > MAX_WORKER_ID || workerId < 0)
            throw new IllegalArgumentException("workerId 超出范围: " + workerId);
        if (datacenterId > MAX_DATACENTER_ID || datacenterId < 0)
            throw new IllegalArgumentException("datacenterId 超出范围: " + datacenterId);
        this.workerId = workerId;
        this.datacenterId = datacenterId;
    }

    public synchronized long nextId() {
        long current = System.currentTimeMillis();

        // 时钟回拨处理: 小幅等待, 大幅拒绝
        if (current < lastTimestamp) {
            long offset = lastTimestamp - current;
            if (offset <= MAX_BACKWARD_MS) {
                // 小幅回拨: 自旋等待
                current = waitUntilAfter(lastTimestamp);
            } else {
                throw new RuntimeException("时钟回拨超过 " + MAX_BACKWARD_MS + "ms, 拒绝发号. offset=" + offset);
            }
        }

        if (current == lastTimestamp) {
            // 同毫秒: 序列号递增
            sequence = (sequence + 1) & SEQUENCE_MASK;
            if (sequence == 0) {
                // 序列号耗尽, 自旋到下一毫秒
                current = waitUntilAfter(lastTimestamp);
            }
        } else {
            // 新毫秒: 序列号归零
            sequence = 0L;
        }
        lastTimestamp = current;

        // 拼装 ID: 时间戳 | 机房 | 机器 | 序列号
        return ((current - EPOCH) << TIMESTAMP_SHIFT)
                | (datacenterId << DATACENTER_ID_SHIFT)
                | (workerId << WORKER_ID_SHIFT)
                | sequence;
    }

    private long waitUntilAfter(long timestamp) {
        long current = System.currentTimeMillis();
        while (current <= timestamp) {
            current = System.currentTimeMillis();
        }
        return current;
    }

    /** 反解 ID 各部分, 方便排查 */
    public static String parse(long id) {
        long sequence = id & SEQUENCE_MASK;
        long workerId = (id >> WORKER_ID_SHIFT) & MAX_WORKER_ID;
        long datacenterId = (id >> DATACENTER_ID_SHIFT) & MAX_DATACENTER_ID;
        long timestamp = (id >> TIMESTAMP_SHIFT) + EPOCH;
        return "ts=" + timestamp + ", dc=" + datacenterId + ", worker=" + workerId + ", seq=" + sequence;
    }
}

/**
 * 号段模式核心逻辑（含双 buffer 预取）
 * 实际生产中应接入 DB 和异步加载线程, 这里展示内存核心结构
 */
public class SegmentIdGenerator {
    // 当前 buffer: 从中分配 ID
    private AtomicLong currentId;
    private AtomicLong currentMax;
    // 预取 buffer: 后台加载
    private AtomicLong nextId;
    private AtomicLong nextMax;
    private final Object lock = new Object();
    // 模拟 DB 获取号段
    public long nextId() {
        while (true) {
            long id = currentId.incrementAndGet();
            if (id <= currentMax.get()) {
                return id;
            }
            // 当前 buffer 耗尽, 尝试切换
            synchronized (lock) {
                if (currentId.get() > currentMax.get()) {
                    // 如果 next buffer 已加载, 直接切换
                    if (nextId != null && nextId.get() <= nextMax.get()) {
                        currentId = nextId;
                        currentMax = nextMax;
                        nextId = null;
                        nextMax = null;
                    } else {
                        // 否则同步从 DB 加载 (生产中应异步)
                        long[] seg = loadFromDb();
                        currentId = new AtomicLong(seg[0]);
                        currentMax = new AtomicLong(seg[1]);
                    }
                }
            }
        }
    }

    private long[] loadFromDb() {
        // 模拟: UPDATE leaf_alloc SET max_id=max_id+1000 WHERE biz_tag='order'
        long start = 1; // DB 返回
        long end = 1000;
        return new long[]{start, end};
    }
}
